    public void handleTrade(Client client, Object message)
    {
        //
        // {
        //     "topic":"SPOT_ADA_USDT@trade",
        //     "ts":1618820361552,
        //     "data":{
        //         "symbol":"SPOT_ADA_USDT",
        //         "price":1.27988,
        //         "size":300,
        //         "side":"BUY",
        //         "source":0
        //     }
        // }
        //
        Object topic = this.safeString(message, "topic");
        Object timestamp = this.safeInteger(message, "ts");
        Object data = this.safeValue(message, "data");
        Object marketId = this.safeString(data, "symbol");
        Object market = this.safeMarket(marketId);
        Object symbol = Helpers.GetValue(market, "symbol");
        Object trade = this.parseWsTrade(this.extend(data, new java.util.HashMap<String, Object>() {{
            put( "timestamp", timestamp );
        }}), market);
        Object tradesArray = this.safeValue(this.trades, symbol);
        if (Helpers.isTrue(Helpers.isEqual(tradesArray, null)))
        {
            Object limit = this.safeInteger(this.options, "tradesLimit", 1000);
            tradesArray = new ArrayCache(((Number)limit).intValue());
        }
        Helpers.callDynamically(tradesArray, "append", new Object[]{trade});
        Helpers.addElementToObject(this.trades, symbol, tradesArray);
        client.resolve(tradesArray, topic);
    }

    public Object parseWsTrade(Object trade, Object... optionalArgs)
    {
        //
        //     {
        //         "symbol":"SPOT_ADA_USDT",
        //         "timestamp":1618820361552,
        //         "price":1.27988,
        //         "size":300,
        //         "side":"BUY",
        //         "source":0
        //     }
        // private trade
        //    {
        //     "msgType": 0,  // execution report
        //     "symbol": "SPOT_BTC_USDT",
        //     "clientOrderId": 0,
        //     "orderId": 54774393,
        //     "type": "MARKET",
        //     "side": "BUY",
        //     "quantity": 0.0,
        //     "price": 0.0,
        //     "tradeId": 56201985,
        //     "executedPrice": 23534.06,
        //     "executedQuantity": 0.00040791,
        //     "fee": 2.1E-7,
        //     "feeAsset": "BTC",
        //     "totalExecutedQuantity": 0.00040791,
        //     "avgPrice": 23534.06,
        //     "status": "FILLED",
        //     "reason": "",
        //     "orderTag": "default",
        //     "totalFee": 2.1E-7,
        //     "feeCurrency": "BTC",
        //     "totalRebate": 0,
        //     "rebateCurrency": "USDT",
        //     "visible": 0.0,
        //     "timestamp": 1675406261689,
        //     "reduceOnly": false,
        //     "maker": false
        //   }
        //
        Object market = Helpers.getArg(optionalArgs, 0, null);
        Object marketId = this.safeString(trade, "symbol");
        market = this.safeMarket(marketId, market);
        Object symbol = Helpers.GetValue(market, "symbol");
        Object price = this.safeString2(trade, "executedPrice", "price");
        Object amount = this.safeString2(trade, "executedQuantity", "size");
        Object cost = Precise.stringMul(price, amount);
        Object side = this.safeStringLower(trade, "side");
        Object timestamp = this.safeInteger(trade, "timestamp");
        Object maker = this.safeBool(trade, "maker");
        Object takerOrMaker = null;
        if (Helpers.isTrue(!Helpers.isEqual(maker, null)))
        {
            takerOrMaker = ((Helpers.isTrue(maker))) ? "maker" : "taker";
        }
        Object type = this.safeStringLower(trade, "type");
        Object fee = null;
        Object feeCost = this.safeNumber(trade, "fee");
        if (Helpers.isTrue(!Helpers.isEqual(feeCost, null)))
        {
            final Object finalFeeCost = feeCost;
            fee = new java.util.HashMap<String, Object>() {{
                put( "cost", finalFeeCost );
                put( "currency", Woo.this.safeCurrencyCode(Woo.this.safeString(trade, "feeCurrency")) );
            }};
        }
        final Object finalTakerOrMaker = takerOrMaker;
        final Object finalFee = fee;
        return this.safeTrade(new java.util.HashMap<String, Object>() {{
            put( "id", Woo.this.safeString(trade, "tradeId") );
            put( "timestamp", timestamp );
            put( "datetime", Woo.this.iso8601(timestamp) );
            put( "symbol", symbol );
            put( "side", side );
            put( "price", price );
            put( "amount", amount );
            put( "cost", cost );
            put( "order", Woo.this.safeString(trade, "orderId") );
            put( "takerOrMaker", finalTakerOrMaker );
            put( "type", type );
            put( "fee", finalFee );
            put( "info", trade );
        }}, market);
    }

    public Object checkRequiredUid(Object... optionalArgs)
    {
        Object error = Helpers.getArg(optionalArgs, 0, true);
        if (Helpers.isTrue(Helpers.isTrue((Helpers.isEqual(this.uid, null))) || Helpers.isTrue((Helpers.isEqual(this.uid, "")))))
        {
            if (Helpers.isTrue(error))
            {
                throw new AuthenticationError((String)Helpers.add(this.id, " requires `uid` credential (woox calls it `application_id`)")) ;
            } else
            {
                return false;
            }
        }
        return true;
    }

    public java.util.concurrent.CompletableFuture<Object> authenticate(Object... optionalArgs)
    {

        return java.util.concurrent.CompletableFuture.supplyAsync(() -> {

            Object parameters = Helpers.getArg(optionalArgs, 0, new java.util.HashMap<String, Object>() {{}});
            this.checkRequiredCredentials();
            Object url = Helpers.add(Helpers.add(Helpers.GetValue(Helpers.GetValue(Helpers.GetValue(this.urls, "api"), "ws"), "private"), "/"), this.uid);
            Client client = this.client(url);
            Object messageHash = "authenticated";
            Object eventVar = "auth";
            io.github.ccxt.ws.Future future = client.reusableFuture((String)messageHash);
            Object authenticated = this.safeValue(client.subscriptions, messageHash);
            if (Helpers.isTrue(Helpers.isEqual(authenticated, null)))
            {
                Object ts = String.valueOf(this.nonce());
                Object auth = Helpers.add("|", ts);
                Object signature = this.hmac(this.encode(auth), this.encode(this.secret), sha256());
                Object request = new java.util.HashMap<String, Object>() {{
                    put( "event", eventVar );
                    put( "params", new java.util.HashMap<String, Object>() {{
                        put( "apikey", Woo.this.apiKey );
                        put( "sign", signature );
                        put( "timestamp", ts );
                    }} );
                }};
                Object message = this.extend(request, parameters);
                this.watch(url, messageHash, message, messageHash, message);
            }
            return ((io.github.ccxt.ws.Future)future).getFuture().join();
        });

    }

    public java.util.concurrent.CompletableFuture<Object> watchPrivate(Object messageHash, Object message, Object... optionalArgs)
    {

        return java.util.concurrent.CompletableFuture.supplyAsync(() -> {

            Object parameters = Helpers.getArg(optionalArgs, 0, new java.util.HashMap<String, Object>() {{}});
            (this.authenticate(parameters)).join();
            Object url = Helpers.add(Helpers.add(Helpers.GetValue(Helpers.GetValue(Helpers.GetValue(this.urls, "api"), "ws"), "private"), "/"), this.uid);
            Object requestId = this.requestId(url);
            Object subscribe = new java.util.HashMap<String, Object>() {{
                put( "id", requestId );
            }};
            Object request = this.extend(subscribe, message);
            return (this.watch(url, messageHash, request, messageHash, subscribe)).join();
        });

    }

    public java.util.concurrent.CompletableFuture<Object> watchPrivateMultiple(Object messageHashes, Object message, Object... optionalArgs)
    {

        return java.util.concurrent.CompletableFuture.supplyAsync(() -> {

            Object parameters = Helpers.getArg(optionalArgs, 0, new java.util.HashMap<String, Object>() {{}});
            (this.authenticate(parameters)).join();
            Object url = Helpers.add(Helpers.add(Helpers.GetValue(Helpers.GetValue(Helpers.GetValue(this.urls, "api"), "ws"), "private"), "/"), this.uid);
            Object requestId = this.requestId(url);
            Object subscribe = new java.util.HashMap<String, Object>() {{
                put( "id", requestId );
            }};
            Object request = this.extend(subscribe, message);
            return (this.watchMultiple(url, messageHashes, request, messageHashes, subscribe)).join();
        });

    }

